import{_ as n,o as s,c as t,a2 as e}from"./chunks/framework.DIWxYxwh.js";const R=JSON.parse('{"title":"RK3588 与 RK1828 硬件架构及 AI 计算平台入门","description":"","frontmatter":{},"headers":[],"relativePath":"LLM推理/RK3588 与 RK1828 硬件架构.md","filePath":"LLM推理/RK3588 与 RK1828 硬件架构.md","lastUpdated":1792058828000}'),p={name:"LLM推理/RK3588 与 RK1828 硬件架构.md"};function l(r,a,i,o,d,c){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="rk3588-与-rk1828-硬件架构及-ai-计算平台入门" tabindex="-1">RK3588 与 RK1828 硬件架构及 AI 计算平台入门 <a class="header-anchor" href="#rk3588-与-rk1828-硬件架构及-ai-计算平台入门" aria-label="Permalink to &quot;RK3588 与 RK1828 硬件架构及 AI 计算平台入门&quot;">​</a></h1><blockquote><p>本文是 RK3588 AI 模型部署开源指南的第一篇，介绍硬件架构、AI 计算资源、软件生态及模型部署的基本概念，为后续大语言模型和视觉模型实战建立基础。</p></blockquote><h2 id="_1-rk3588-与-rk1828-简介" tabindex="-1">1. RK3588 与 RK1828 简介 <a class="header-anchor" href="#_1-rk3588-与-rk1828-简介" aria-label="Permalink to &quot;1. RK3588 与 RK1828 简介&quot;">​</a></h2><p>RK3588 是一款集成 CPU、GPU、NPU 和多媒体处理能力的 SoC，适合运行 Linux、视觉算法及边缘 AI 应用。</p><p>RK1828 则是一款 AI 协处理器，可通过高速接口连接 RK3588 等主控平台，为系统扩展 AI 计算能力。它并不是 RK3588 的替代品，而是面向更高 AI 算力需求的扩展方案。</p><table tabindex="0"><thead><tr><th>项目</th><th>RK3588</th><th>RK1828</th></tr></thead><tbody><tr><td>产品定位</td><td>主控 SoC</td><td>AI 协处理器</td></tr><tr><td>CPU</td><td>4× Cortex-A76 + 4× Cortex-A55</td><td>三核 RISC-V 64 位处理器</td></tr><tr><td>AI 算力</td><td>NPU 标称 6 TOPS INT8</td><td>标称 20 TOPS INT8</td></tr><tr><td>内存</td><td>由开发板配置决定</td><td>5 GB 片上堆叠 DRAM</td></tr><tr><td>主要用途</td><td>系统运行、视觉推理、应用调度</td><td>扩展 AI 推理能力</td></tr><tr><td>连接方式</td><td>系统主控</td><td>可通过 PCIe 2.1 连接主控</td></tr></tbody></table><p>以上 RK1828 规格参考 Firefly 公开的 AI 计算模块文档；具体产品形态和可用资源应以实际模块及开发板为准。</p><p>参考资料：<a href="https://github.com/Firefly-docs/products-docs/blob/master/en/Accessories/RK1828/started.md" target="_blank" rel="noreferrer">RK1828 AI 计算模块介绍</a>、<a href="https://www.rock-chips.com/uploads/pdf/2022.8.26/191/RK3588%20Brief%20Datasheet.pdf" target="_blank" rel="noreferrer">Rockchip RK3588 数据手册</a>。</p><h2 id="_2-rk3588-硬件架构" tabindex="-1">2. RK3588 硬件架构 <a class="header-anchor" href="#_2-rk3588-硬件架构" aria-label="Permalink to &quot;2. RK3588 硬件架构&quot;">​</a></h2><p>RK3588 的主要计算资源包括 CPU、GPU 和 NPU。</p><h3 id="_2-1-cpu" tabindex="-1">2.1 CPU <a class="header-anchor" href="#_2-1-cpu" aria-label="Permalink to &quot;2.1 CPU&quot;">​</a></h3><p>RK3588 采用八核 CPU 架构：</p><ul><li>4 个 Cortex-A76 高性能核心。</li><li>4 个 Cortex-A55 高能效核心。</li></ul><p>CPU 主要负责操作系统、业务逻辑、图像预处理、模型输入输出处理、网络通信及任务调度。</p><h3 id="_2-2-gpu" tabindex="-1">2.2 GPU <a class="header-anchor" href="#_2-2-gpu" aria-label="Permalink to &quot;2.2 GPU&quot;">​</a></h3><p>RK3588 集成 ARM Mali-G610 MC4 GPU，主要用于图形渲染及受相应驱动和框架支持的计算任务。</p><p>在 AI 应用中，GPU 可以承担图形界面、图像显示等工作，但不能直接将 GPU 与 NPU 视为同一种推理执行环境。</p><h3 id="_2-3-npu" tabindex="-1">2.3 NPU <a class="header-anchor" href="#_2-3-npu" aria-label="Permalink to &quot;2.3 NPU&quot;">​</a></h3><p>RK3588 集成三核 NPU，标称总 INT8 算力为 6 TOPS。</p><p>NPU 主要用于执行经过相应工具链转换、且算子和数据类型受到支持的神经网络模型，例如图像分类、目标检测和图像分割。</p><p>实际推理性能不仅取决于峰值算力，还受到模型结构、量化方式、内存访问、预处理及运行时调度影响。</p><h2 id="_3-rk1828-如何扩展-rk3588-的-ai-能力" tabindex="-1">3. RK1828 如何扩展 RK3588 的 AI 能力 <a class="header-anchor" href="#_3-rk1828-如何扩展-rk3588-的-ai-能力" aria-label="Permalink to &quot;3. RK1828 如何扩展 RK3588 的 AI 能力&quot;">​</a></h2><p>在需要运行更大模型或增加 AI 任务吞吐量的场景下，可以考虑 RK3588 搭配 RK1828 的方案。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────┐</span></span>
<span class="line"><span>│             RK3588              │</span></span>
<span class="line"><span>│                                 │</span></span>
<span class="line"><span>│ Linux / 应用程序 / 网络服务      │</span></span>
<span class="line"><span>│ CPU / GPU / 本地 NPU            │</span></span>
<span class="line"><span>└────────────────┬────────────────┘</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>              PCIe 2.1</span></span>
<span class="line"><span>                 │</span></span>
<span class="line"><span>┌────────────────▼────────────────┐</span></span>
<span class="line"><span>│             RK1828              │</span></span>
<span class="line"><span>│                                 │</span></span>
<span class="line"><span>│ AI 协处理器                     │</span></span>
<span class="line"><span>│ 20 TOPS INT8                    │</span></span>
<span class="line"><span>│ 5 GB 片上堆叠 DRAM              │</span></span>
<span class="line"><span>└─────────────────────────────────┘</span></span></code></pre></div><p>典型分工如下：</p><table tabindex="0"><thead><tr><th>任务</th><th>建议承担方</th></tr></thead><tbody><tr><td>Linux 系统与业务应用</td><td>RK3588</td></tr><tr><td>摄像头输入及应用逻辑</td><td>RK3588</td></tr><tr><td>轻量级视觉模型</td><td>可先评估 RK3588 NPU</td></tr><tr><td>更高 AI 算力需求</td><td>评估 RK1828</td></tr><tr><td>大语言模型或视觉语言模型</td><td>根据模型、内存及工具链支持情况选择</td></tr></tbody></table><p>RK1828 的公开产品资料提及 3B～7B 参数规模的 LLM/VLM 应用，但这不代表所有同等规模的模型都能直接部署。模型结构、量化方式、运行时版本和实际内存需求仍需逐项确认。</p><p>还需要注意，两个处理器的标称 TOPS 不能直接相加后当作单个模型的实际性能。主控和协处理器之间的通信、内存及软件调度都会影响最终表现。</p><p>参考资料：<a href="https://github.com/Firefly-docs/products-docs/blob/master/en/Accessories/RK1828/started.md" target="_blank" rel="noreferrer">Firefly RK1828 模块说明</a>。</p><h2 id="_4-ai-软件生态与工具链" tabindex="-1">4. AI 软件生态与工具链 <a class="header-anchor" href="#_4-ai-软件生态与工具链" aria-label="Permalink to &quot;4. AI 软件生态与工具链&quot;">​</a></h2><p>在 RK3588 平台上部署 AI 模型，通常需要经过模型转换、量化、导出和板端推理几个阶段。</p><h3 id="_4-1-主要工具链" tabindex="-1">4.1 主要工具链 <a class="header-anchor" href="#_4-1-主要工具链" aria-label="Permalink to &quot;4.1 主要工具链&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具链</th><th>主要用途</th><th>典型场景</th></tr></thead><tbody><tr><td>RKNN-Toolkit2</td><td>模型转换、量化与验证</td><td>RK3588 视觉模型</td></tr><tr><td>RKNN Runtime / Lite2</td><td>板端模型推理</td><td>分类、检测、分割</td></tr><tr><td>RKLLM-Toolkit</td><td>大语言模型转换与导出</td><td>支持的 LLM</td></tr><tr><td>RKLLM Runtime</td><td>大语言模型板端推理</td><td>文本生成与问答</td></tr><tr><td>RKNN3 工具链</td><td>新一代模型转换与运行生态</td><td>需根据具体硬件及协处理器支持情况选用</td></tr></tbody></table><p>官方项目：</p><ul><li><a href="https://github.com/airockchip/rknn-toolkit2" target="_blank" rel="noreferrer">RKNN-Toolkit2</a></li><li><a href="https://github.com/airockchip/rknpu2" target="_blank" rel="noreferrer">RKNN Runtime</a></li><li><a href="https://github.com/airockchip/rknn-llm" target="_blank" rel="noreferrer">RKLLM</a></li><li><a href="https://github.com/airockchip/rknn3-toolkit" target="_blank" rel="noreferrer">RKNN3 Toolkit</a></li><li><a href="https://github.com/airockchip/rknn3-model-zoo" target="_blank" rel="noreferrer">RKNN3 Model Zoo</a></li></ul><p><strong>工具链选择需要特别注意：</strong> RKNN-Toolkit2 与 RKNN3 Toolkit 并不是可以直接互换的同一版本工具。RK3588 本地 NPU 部署和 RK3588 搭配 RK1828 的协处理器部署，也可能使用不同的模型格式、Runtime 和通信组件。应根据官方项目列出的支持平台选择正确方案。</p><h2 id="_5-ai-模型的基本部署流程" tabindex="-1">5. AI 模型的基本部署流程 <a class="header-anchor" href="#_5-ai-模型的基本部署流程" aria-label="Permalink to &quot;5. AI 模型的基本部署流程&quot;">​</a></h2><p>无论是视觉模型还是大语言模型，都可以按照以下思路理解部署过程：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原始模型</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>检查模型结构与硬件兼容性</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>使用对应工具链转换和量化</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>导出目标平台模型文件</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>部署 Runtime 与模型</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>加载模型并执行推理</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>验证精度、速度和资源占用</span></span></code></pre></div><h3 id="_5-1-视觉模型" tabindex="-1">5.1 视觉模型 <a class="header-anchor" href="#_5-1-视觉模型" aria-label="Permalink to &quot;5.1 视觉模型&quot;">​</a></h3><p>视觉模型通常采用 RKNN 工具链，典型流程为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PyTorch / ONNX</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>RKNN-Toolkit2</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>量化与转换</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>.rknn 模型</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>RKNN Runtime</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>RK3588 NPU 推理</span></span></code></pre></div><p>入门时建议从图像分类模型开始，再逐步学习目标检测和图像分割。</p><h3 id="_5-2-大语言模型" tabindex="-1">5.2 大语言模型 <a class="header-anchor" href="#_5-2-大语言模型" aria-label="Permalink to &quot;5.2 大语言模型&quot;">​</a></h3><p>大语言模型通常采用与模型和硬件版本匹配的 RKLLM 工具链，典型流程为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原始模型权重与 Tokenizer</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>检查模型兼容性</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>RKLLM-Toolkit</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>量化与模型导出</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>.rkllm 模型</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>RKLLM Runtime</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>Prompt 输入与文本生成</span></span></code></pre></div><p>大语言模型部署还需要重点关注权重大小、量化精度、上下文长度、KV Cache、运行内存及生成速度。</p><p>如果目标是使用 RK1828 扩展大模型能力，应先确认该模块所配套的官方 SDK、Runtime 和模型示例，而不是直接将 RK3588 本地 NPU 的部署流程照搬到协处理器上。</p><h2 id="_6-后续学习路线" tabindex="-1">6. 后续学习路线 <a class="header-anchor" href="#_6-后续学习路线" aria-label="Permalink to &quot;6. 后续学习路线&quot;">​</a></h2><p>建议按照以下顺序学习：</p><ol><li><strong>环境准备：</strong> 确认开发板型号、系统版本、驱动和工具链。</li><li><strong>视觉模型入门：</strong> 完成一个分类模型的转换与板端推理。</li><li><strong>大语言模型部署：</strong> 完成一个受支持的 LLM 的转换、量化及文本生成。</li><li><strong>性能测试：</strong> 测量推理延迟、FPS、tokens/s 和内存占用。</li><li><strong>多模型协同：</strong> 将视觉识别结果传给 LLM，构建自然语言分析应用。</li><li><strong>RK1828 扩展：</strong> 在确认硬件、SDK 和 Runtime 兼容后，测试协处理器上的 AI 推理方案。</li></ol><h2 id="_7-参考资料" tabindex="-1">7. 参考资料 <a class="header-anchor" href="#_7-参考资料" aria-label="Permalink to &quot;7. 参考资料&quot;">​</a></h2><ul><li><a href="https://www.rock-chips.com/uploads/pdf/2022.8.26/191/RK3588%20Brief%20Datasheet.pdf" target="_blank" rel="noreferrer">Rockchip RK3588 数据手册</a></li><li><a href="https://github.com/Firefly-docs/products-docs/blob/master/en/Accessories/RK1828/started.md" target="_blank" rel="noreferrer">Firefly RK1828 AI 计算模块</a></li><li><a href="https://github.com/airockchip/rknn-toolkit2" target="_blank" rel="noreferrer">RKNN-Toolkit2 官方仓库</a></li><li><a href="https://github.com/airockchip/rknn-llm" target="_blank" rel="noreferrer">RKLLM 官方仓库</a></li><li><a href="https://github.com/airockchip/rknn3-toolkit" target="_blank" rel="noreferrer">RKNN3 Toolkit 官方仓库</a></li><li><a href="https://github.com/airockchip/rknn3-model-zoo" target="_blank" rel="noreferrer">RKNN3 Model Zoo 官方仓库</a></li></ul><hr><p><strong>本文定位：</strong> 作为开源学习指南的硬件与软件生态入门篇。后续章节建议分别深入介绍 RK3588 上的大语言模型部署、视觉模型部署，以及 RK3588 搭配 RK1828 的协处理器部署实践。</p>`,55)])])}const k=n(p,[["render",l]]);export{R as __pageData,k as default};
